//! 🧪️ Original payload pages survive denied publication, captured reads and funded cancellation.
use super::*;
use semio_framework_value::{retained_clone::RetainedCloneGrant,retirement::{controlled::ControlledRetirement,shared::sealed::SealedShared}};
use update::ToolRunPayloadStreamUpdate;
fn observe<T>(f:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);(value,(heap.requested_bytes,heap.released_bytes))}
fn check_read<const N:usize>(view:ToolRunPayloadView<'_>,offset:usize){let(bytes,heap)=observe(||view.read_fixed::<N>(offset).unwrap());assert_eq!(heap,(0,0));assert_eq!(bytes,std::array::from_fn(|i|(((offset+i)*17+3)%251)as u8));}
fn close(mut owner:ToolRunPayloadStreamUpdate,g:RetainedCloneGrant)->(usize,usize){owner.begin_close();let mut heap=(0,0);for _ in 0..100000{if owner.terminal_is_empty(){assert_eq!(observe(||drop(owner)).1,(0,0));return heap;}let(step,h)=observe(||owner.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),h);heap.0+=h.0;heap.1+=h.1;}panic!("original payload closure did not reach its empty terminal");}
fn retire<T:semio_framework_value::retirement::RetireOwned>(input:T,g:RetainedCloneGrant)->(usize,usize){let(owner,h)=observe(||ControlledRetirement::new(input).ok().unwrap());let mut owner=owner;let mut heap=h;for _ in 0..100000{if owner.terminal_is_empty(){assert_eq!(observe(||drop(owner)).1,(0,0));return heap;}let(step,h)=observe(||owner.step(g).unwrap());assert!(step.progress().fits(g));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),h);heap.0+=h.0;heap.1+=h.1;}panic!("original directory closure did not reach its empty terminal");}
#[test]
fn original_payload_stream_retains_native_pages_across_denial_disconnect_and_capture(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["policy"];let g=RetainedCloneGrant{maximum_items:p["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:p["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:p["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:p["maximumDepth"].as_u64().unwrap()as usize};let identity=ToolRunIdentity{id:crate::ToolRunId{app_instance_id:7,run:17},generation:3,base_revision:[0x11;32]};let total=law["totalBytes"].as_u64().unwrap()as usize;let stride=law["chunkBytes"].as_u64().unwrap()as usize;let mut original=None;let mut capture=None;let mut heap=(0,0);let mut turns=0;
 for (index,length)in law["lengths"].as_array().unwrap().iter().enumerate(){let length=length.as_u64().unwrap()as usize;let offset=index*stride;let(input,h)=observe(||Some((offset..offset+length).map(|i|((i*17+3)%251)as u8).collect::<Vec<_>>()));heap.0+=h.0;heap.1+=h.1;let mut input=input;let pointer=input.as_ref().unwrap().as_ptr();let update=ToolRunPayloadUpdate::Range{publication:41,total_bytes:total as u64,offset:offset as u64,chunk_bytes:stride as u32,final_chunk:offset+length==total};let mut owner=ToolRunPayloadStreamUpdate::empty();let d=ToolRunPayloadStreamUpdate::birth_demand();assert!(d.copy_bytes<=g.maximum_copy_bytes);
  for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(result,h)=observe(||owner.admit(&mut original,&mut input,identity,update,denied).unwrap());assert!(result.is_none());assert_eq!(h,(0,0));assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);}
  if index>0{let original_pointer=original.as_ref().unwrap().identity();for (foreign,change)in[(identity.next_generation(),update),(ToolRunIdentity{base_revision:[0x12;32],..identity},update),(identity,ToolRunPayloadUpdate::Range{publication:42,total_bytes:total as u64,offset:offset as u64,chunk_bytes:stride as u32,final_chunk:offset+length==total}),(identity,ToolRunPayloadUpdate::Range{publication:41,total_bytes:total as u64,offset:0,chunk_bytes:stride as u32,final_chunk:false})]{let(result,h)=observe(||owner.admit(&mut original,&mut input,foreign,change,g));assert!(result.is_err());assert_eq!(h,(0,0));assert_eq!(original.as_ref().unwrap().identity(),original_pointer);assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);}}
  let(birth,h)=observe(||owner.admit(&mut original,&mut input,identity,update,g).unwrap().unwrap());assert!(birth.fits(g));assert_eq!(h,(birth.retained_capacity_bytes,birth.released_bytes));heap.0+=h.0;heap.1+=h.1;
  while !owner.complete(){let d=owner.demand().unwrap();assert!(d.copy_bytes<=g.maximum_copy_bytes,"phase quote={d:?}");for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(step,h)=observe(||owner.advance(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(h,(0,0));}if d.capacity_bytes>0{let(step,h)=observe(||owner.advance(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g}).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(h,(0,0));}let(step,h)=observe(||owner.advance(g).unwrap());assert!(step.progress().fits(g));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),h);heap.0+=h.0;heap.1+=h.1;turns+=1;assert!(turns<100000);}
  let((result,receipt),h)=observe(||owner.take(g).unwrap().unwrap());assert!(receipt.fits(g));assert_eq!(h,(0,0));assert_eq!(result.get().pages.get(index).unwrap().as_ptr(),pointer);assert!(result.get().borrowed_view(identity.next_generation()).is_none());let view=result.get().borrowed_view(identity).unwrap();assert_eq!(view.received_bytes(),offset+length);assert_eq!(view.complete(),offset+length==total);assert!(view.read_fixed::<65>(0).is_none());assert!(view.read_fixed::<1>(offset+length).is_none());if index==0{let((alias,receipt),h)=observe(||result.try_duplicate(g).unwrap());assert!(receipt.fits(g));assert_eq!(h,(0,0));capture=Some(alias);}let h=close(owner,g);heap.0+=h.0;heap.1+=h.1;original=Some(result);
 }
 let view=original.as_ref().unwrap().get().borrowed_view(identity).unwrap();for row in law["reads"].as_array().unwrap(){let offset=row[0].as_u64().unwrap()as usize;match row[1].as_u64().unwrap(){64=>check_read::<64>(view,offset),12=>check_read::<12>(view,offset),17=>check_read::<17>(view,offset),24=>check_read::<24>(view,offset),4=>check_read::<4>(view,offset),_=>panic!("undeclared portable native fixed read")}}assert_eq!(view.page_count(),8);assert!(original.as_ref().unwrap().get().contiguous().is_none());let captured=capture.as_ref().unwrap().get().borrowed_view(identity).unwrap();assert_eq!(captured.page_count(),1);assert_eq!(captured.received_bytes(),stride);assert!(!captured.complete());let h=retire(original.take().unwrap(),g);heap.0+=h.0;heap.1+=h.1;assert!(capture.as_ref().unwrap().get().borrowed_view(identity).unwrap().read_fixed::<17>(stride-17).is_some());let h=retire(capture.take().unwrap(),g);heap.0+=h.0;heap.1+=h.1;assert_eq!(heap.0,heap.1);eprintln!("[DEBUG] original payload 480148bytes 8pages sameOriginalVectors denialAllFrontiers captureSurvivesSuccessor disconnectReadBoundary heapReturned={} turns={turns}",heap.1);
}

#[test]
fn original_payload_stream_returns_every_cancelled_native_prefix(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:131072,maximum_release_bytes:131072,maximum_depth:64};let identity=ToolRunIdentity::new(crate::ToolRunId{app_instance_id:7,run:17},[0x11;32]);
 for prefix in law["cancelPrefixes"].as_array().unwrap(){let prefix=prefix.as_u64().unwrap()as usize;let(input,h)=observe(||Some(vec![19;65536]));let mut heap=h;let mut input=input;let pointer=input.as_ref().unwrap().as_ptr();let mut previous=None;let mut owner=ToolRunPayloadStreamUpdate::empty();let(receipt,h)=observe(||owner.admit(&mut previous,&mut input,identity,ToolRunPayloadUpdate::Range{publication:41,total_bytes:480148,offset:0,chunk_bytes:65536,final_chunk:false},g).unwrap().unwrap());assert!(receipt.fits(g));heap.0+=h.0;heap.1+=h.1;
  for _ in 0..prefix{if owner.complete(){break;}let(step,h)=observe(||owner.advance(g).unwrap());assert!(step.progress().fits(g));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),h);heap.0+=h.0;heap.1+=h.1;}
  if let Some(input)=owner.original_input_identity(){assert_eq!(input,pointer as usize);}owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(g.maximum_copy_bytes).unwrap();let mut denied=RetainedCloneGrant{maximum_items:0,..g};let(step,h)=observe(||owner.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(h,(0,0));if d.release_bytes>0{denied=RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g};let(step,h)=observe(||owner.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(h,(0,0));}let(step,h)=observe(||owner.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),h);heap.0+=h.0;heap.1+=h.1;}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));assert_eq!(heap.0,heap.1);eprintln!("[DEBUG] original payload cancelledPrefix={prefix} physicalReturn={} terminalDrop0",heap.1);
 }
}

#[test]
fn original_payload_stream_keeps_complete_capture_visible_during_pending_publication(){
 let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:131072,maximum_release_bytes:131072,maximum_depth:64};let identity=ToolRunIdentity::new(crate::ToolRunId{app_instance_id:7,run:17},[0x11;32]);let mut previous=None;let mut visible=None;let mut heap=(0,0);
 for update in[ToolRunPayloadUpdate::Replace,ToolRunPayloadUpdate::Range{publication:41,total_bytes:128,offset:0,chunk_bytes:64,final_chunk:false}]{let length=if matches!(update,ToolRunPayloadUpdate::Replace){17}else{64};let(input,h)=observe(||Some(vec![23;length]));heap.0+=h.0;heap.1+=h.1;let mut input=input;let mut owner=ToolRunPayloadStreamUpdate::empty();let(p,h)=observe(||owner.admit(&mut previous,&mut input,identity,update,g).unwrap().unwrap());assert!(p.fits(g));heap.0+=h.0;heap.1+=h.1;for _ in 0..100000{if owner.complete(){break;}if let Some(visible)=visible.as_ref(){let visible:&SealedShared<ToolRunPayloadStream>=visible;let view=visible.get().borrowed_view(identity).unwrap();assert!(view.complete());assert_eq!(view.read_fixed::<17>(0),Some([23;17]));}let(step,h)=observe(||owner.advance(g).unwrap());assert!(step.progress().fits(g));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),h);heap.0+=h.0;heap.1+=h.1;}assert!(owner.complete());let((output,p),h)=observe(||owner.take(g).unwrap().unwrap());assert!(p.fits(g));assert_eq!(h,(0,0));if visible.is_none(){let((capture,p),h)=observe(||output.try_duplicate(g).unwrap());assert!(p.fits(g));assert_eq!(h,(0,0));visible=Some(capture);}else{assert!(!output.get().borrowed_view(identity).unwrap().complete());}let h=close(owner,g);heap.0+=h.0;heap.1+=h.1;previous=Some(output);}
 let view=visible.as_ref().unwrap().get().borrowed_view(identity).unwrap();assert!(view.complete());assert_eq!(view.total_bytes(),17);assert_eq!(view.read_fixed::<17>(0),Some([23;17]));let h=retire(previous.take().unwrap(),g);heap.0+=h.0;heap.1+=h.1;assert_eq!(visible.as_ref().unwrap().get().borrowed_view(identity).unwrap().read_fixed::<17>(0),Some([23;17]));let h=retire(visible.take().unwrap(),g);heap.0+=h.0;heap.1+=h.1;assert_eq!(heap.0,heap.1);eprintln!("[DEBUG] original complete publication remains visible through funded pending successor and cancellation physicalReturn={}",heap.1);
}
